+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Snake Game</title>
+    <style>
+        body {
+            display: flex;
+            justify-content: center;
+            align-items: center;
+            min-height: 100vh;
+            margin: 0;
+            padding: 20px;
+            background: #090d16;
+        }
+        .game-container {
+            background: rgba(16, 24, 40, 0.75);
+            backdrop-filter: blur(20px);
+            padding: 20px;
+            border-radius: 10px;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.4);
+        }
+        .game-header {
+            display: flex;
+            justify-content: space-between;
+            padding: 12px 20px;
+        }
+        .score {
+            font-family: 'Inter', sans-serif;
+            font-size: 24px;
+            color: #fff;
+        }
+        .high-score {
+            font-family: 'Inter', sans-serif;
+            font-size: 24px;
+            color: #fff;
+        }
+        .start-game-overlay {
+            position: absolute;
+            top: 0;
+            left: 0;
+            width: 100%;
+            height: 100%;
+            background: rgba(0, 0, 0, 0.5);
+            display: flex;
+            justify-content: center;
+            align-items: center;
+            flex-direction: column;
+        }
+        .start-game-button {
+            background: #fff;
+            padding: 10px 20px;
+            border: none;
+            border-radius: 5px;
+            cursor: pointer;
+        }
+        .game-over-overlay {
+            position: absolute;
+            top: 0;
+            left: 0;
+            width: 100%;
+            height: 100%;
+            background: rgba(0, 0, 0, 0.5);
+            display: none;
+            justify-content: center;
+            align-items: center;
+            flex-direction: column;
+        }
+        .game-over-button {
+            background: #fff;
+            padding: 10px 20px;
+            border: none;
+            border-radius: 5px;
+            cursor: pointer;
+        }
+        .canvas-container {
+            width: 400px;
+            height: 400px;
+            border: 1px solid #fff;
+        }
+    </style>
+</head>
+<body>
+    <div class="game-container">
+        <div class="game-header">
+            <div class="score">Score: <span id="score">0</span></div>
+            <div class="high-score">High Score: <span id="high-score">0</span></div>
+        </div>
+        <div class="start-game-overlay">
+            <h1>Snake Game</h1>
+            <p>Use arrow keys to move the snake.</p>
+            <button class="start-game-button" onclick="startGame()">Start Game</button>
+        </div>
+        <div class="game-over-overlay">
+            <h1>Game Over</h1>
+            <p>Final Score: <span id="final-score">0</span></p>
+            <button class="game-over-button" onclick="restartGame()">Play Again</button>
+        </div>
+        <div class="canvas-container">
+            <canvas id="game-canvas" width="400" height="400"></canvas>
+        </div>
+    </div>
+    <script>
+        let score = 0;
+        let highScore = 0;
+        let snake = [];
+        let food = null;
+        let direction = 'right';
+        let gameInterval = null;
+        let gameOver = false;
+        const canvas = document.getElementById('game-canvas');
+        const ctx = canvas.getContext('2d');
+        const scoreElement = document.getElementById('score');
+        const highScoreElement = document.getElementById('high-score');
+        const finalScoreElement = document.getElementById('final-score');
+        const startGameOverlay = document.querySelector('.start-game-overlay');
+        const gameOverOverlay = document.querySelector('.game-over-overlay');
+        
+        function startGame() {
+            score = 0;
+            highScore = parseInt(localStorage.getItem('high-score')) || 0;
+            snake = [{x: 200, y: 200}];
+            food = {x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10};
+            direction = 'right';
+            gameOver = false;
+            gameInterval = setInterval(update, 100);
+            startGameOverlay.style.display = 'none';
+        }
+        
+        function update() {
+            if (gameOver) return;
+            ctx.clearRect(0, 0, canvas.width, canvas.height);
+            for (let i = 0; i < snake.length; i++) {
+                ctx.fillStyle = 'green';
+                ctx.fillRect(snake[i].x, snake[i].y, 10, 10);
+            }
+            ctx.fillStyle = 'red';
+            ctx.fillRect(food.x, food.y, 10, 10);
+            
+            let head = snake[0];
+            if (direction === 'right') {
+                head = {x: head.x + 10, y: head.y};
+            } else if (direction === 'left') {
+                head = {x: head.x - 10, y: head.y};
+            } else if (direction === 'up') {
+                head = {x: head.x, y: head.y - 10};
+            } else if (direction === 'down') {
+                head = {x: head.x, y: head.y + 10};
+            }
+            
+            if (head.x < 0 || head.x >= canvas.width || head.y < 0 || head.y >= canvas.height || checkCollision(head)) {
+                gameOver = true;
+                clearInterval(gameInterval);
+                gameOverOverlay.style.display = 'flex';
+                finalScoreElement.textContent = score;
+                if (score > highScore) {
+                    highScore = score;
+                    localStorage.setItem('high-score', highScore);
+                }
+            } else {
+                snake.unshift(head);
+                if (head.x === food.x && head.y === food.y) {
+                    score++;
+                    scoreElement.textContent = score;
+                    food = {x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10};
+                } else {
+                    snake.pop();
+                }
+            }
+        }
+        
+        function checkCollision(head) {
+            for (let i = 1; i < snake.length; i++) {
+                if (head.x === snake[i].x && head.y === snake[i].y) {
+                    return true;
+                }
+            }
+            return false;
+        }
+        
+        function restartGame() {
+            startGameOverlay.style.display = 'flex';
+            gameOverOverlay.style.display = 'none';
+        }
+        
+        document.addEventListener('keydown', (e) => {
+            if (e.key === 'ArrowUp' && direction !== 'down') {
+                direction = 'up';
+            } else if (e.key === 'ArrowDown' && direction !== 'up') {
+                direction = 'down';
+            } else if (e.key === 'ArrowLeft' && direction !== 'right') {
+                direction = 'left';
+            } else if (e.key === 'ArrowRight' && direction !== 'left') {
+                direction = 'right';
+            }
+        });
+    </script>
+</body>
+</html>

